    m.impl("index_add_custom", &index_add_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("index_add_custom", &index_add_custom_impl_npu, "index_add along dim=0");
}
